package com.cowave.shared.response

import com.cowave.shared.exception.BaseErrorCode

class CommonResponse<T>(
    val result: Result,
    val data: T,
    val message: String?,
    val errorCode: String?,
) {
    enum class Result {
        SUCCESS,
        FAIL,
    }

    companion object {
        fun <T> success(
            data: T,
            message: String?,
        ): CommonResponse<T> = CommonResponse(Result.SUCCESS, data, message, null)

        fun <T> success(data: T): CommonResponse<T> = success(data, null)

        fun fail(
            message: String?,
            errorCode: BaseErrorCode,
        ): CommonResponse<*> = CommonResponse(Result.FAIL, null, message, errorCode.type)

        fun fail(errorCode: BaseErrorCode): CommonResponse<*> = CommonResponse(Result.FAIL, null, errorCode.message, errorCode.type)

        fun <T> fail(
            data: T,
            message: String?,
            errorCode: String?,
        ): CommonResponse<T> = CommonResponse(Result.FAIL, data, message, errorCode)
    }
}

