import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.http.converter.HttpMessageNotReadableException
import org.springframework.web.bind.MethodArgumentNotValidException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice

@RestControllerAdvice
class GlobalExceptionAdvice {
    private val logger by logger()

    @ExceptionHandler(SearchException::class)
    fun handleSearchException(e: SearchException): ResponseEntity<CommonResponse<*>> {
        val errorCode = e.getErrorCode()
        val message = e.message ?: errorCode.message
        logger.error(e) { "[SearchException] ${errorCode.type}: ${errorCode.message}" }

        return ResponseEntity
            .status(mapToHttpStatus(errorCode))
            .body(CommonResponse.fail(message, errorCode))
    }

    @ExceptionHandler(BaseException::class)
    fun handleBaseException(e: BaseException): ResponseEntity<CommonResponse<*>> {
        val errorCode = e.getErrorCode()
        val message = e.message ?: errorCode.message
        logger.error(e) { "[BaseException] ${errorCode.type}: $message" }

        return ResponseEntity
            .status(mapToHttpStatus(errorCode))
            .body(CommonResponse.fail(message, errorCode))
    }

    @ExceptionHandler(HttpMessageNotReadableException::class)
    fun handleHttpMessageNotReadable(e: HttpMessageNotReadableException): ResponseEntity<CommonResponse<*>> {
        logger.error(e) { "[HttpMessageNotReadableException] 잘못된 요청 형식: ${e.message}" }

        return ResponseEntity
            .status(HttpStatus.BAD_REQUEST)
            .body(
                CommonResponse.fail(
                    "잘못된 요청 형식입니다. 요청 데이터를 확인해주세요.",
                    ErrorCode.INVALID_QUERY_ERROR,
                ),
            )
    }

    @ExceptionHandler(RuntimeException::class)
    fun handleRuntimeException(e: RuntimeException): ResponseEntity<CommonResponse<*>> {
        logger.error(e) { "[RuntimeException] ${e::class.simpleName}: ${e.message}" }

        return ResponseEntity
            .status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(CommonResponse.fail(ErrorCode.UNHANDLED_RUNTIME_ERROR))
    }

    @ExceptionHandler(Exception::class)
    fun handleException(e: Exception): ResponseEntity<CommonResponse<*>> {
        logger.error(e) { "[Exception] ${e::class.simpleName}: ${e.message}" }

        return ResponseEntity
            .status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(CommonResponse.fail(ErrorCode.INTERNAL_SERVER_ERROR))
    }

    private fun mapToHttpStatus(errorCode: BaseErrorCode): HttpStatus {
        // gRPC Status Code to HTTP Status mapping
        return when (errorCode.grpcStatus) {
            0 -> HttpStatus.OK // OK
            1 -> HttpStatus.REQUEST_TIMEOUT // CANCELLED
            3 -> HttpStatus.BAD_REQUEST // INVALID_ARGUMENT
            5 -> HttpStatus.NOT_FOUND // NOT_FOUND
            6 -> HttpStatus.CONFLICT // ALREADY_EXISTS
            7 -> HttpStatus.FORBIDDEN // PERMISSION_DENIED
            8 -> HttpStatus.TOO_MANY_REQUESTS // RESOURCE_EXHAUSTED
            9 -> HttpStatus.PRECONDITION_FAILED // FAILED_PRECONDITION
            10 -> HttpStatus.CONFLICT // ABORTED
            11 -> HttpStatus.BAD_REQUEST // OUT_OF_RANGE
            12 -> HttpStatus.NOT_IMPLEMENTED // UNIMPLEMENTED
            13 -> HttpStatus.INTERNAL_SERVER_ERROR // INTERNAL
            14 -> HttpStatus.SERVICE_UNAVAILABLE // UNAVAILABLE
            15 -> HttpStatus.INTERNAL_SERVER_ERROR // DATA_LOSS
            16 -> HttpStatus.UNAUTHORIZED // UNAUTHENTICATED
            else -> HttpStatus.INTERNAL_SERVER_ERROR
        }
    }
}

