/**
 * 이벤트 생성을 강제하기 위한 함수형 인터페이스
 */

@FunctionalInterface
fun interface PublishEvent<T> {
    fun publishEvent(): T
}

/**
 * 이벤트 발행을 위한 템플릿 클래스(코틀린 object로 관리)
 */
object EventPublishTemplate {
    private val logger by logger()

    /**
     * 이벤트 발행을 위한 템플릿 메서드
     *
     * @param eventSupplier 실제 이벤트 발행 로직을 담은 콜백
     * @param handleResult 이벤트 발행 후 전송 로직을 담은 콜백
     * @return 콜백 실행 결과
     * @throws Exception 콜백에서 발생한 예외
     */
    fun <T> execute(
        eventSupplier: PublishEvent<T>,
        handleResult: (Result<T>) -> Unit,
    ) {
        runCatching {
            eventSupplier.publishEvent()
        }.onSuccess { event ->
            runCatching {
                handleResult(Result.success(event))
            }.onFailure {
                logger.error { "sendCallback 실행 실패: $it" }
                throw it
            }
        }.onFailure { ex ->
            logger.error { "이벤트 발행 실패: $ex" }
            handleResult(Result.failure(ex))
        }
    }
}

