package com.cowave.search.domain.index.policy

import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.enums.Operation

interface MergeStrategy<T> {
    fun merge(documents: List<ChangedData<T>>): List<ChangedData<T>>

    fun merge(before: ChangedData<T>?, after: ChangedData<T>): ChangedData<T>? =
        when {
            before == null -> after

            // c -> c : 중복 이슈, after 1개만 수행
            // u -> c : 비정상, c를 수행하여 최신화
            // d -> c : d 무시, c만 수행 (over-write)
            after.op == Operation.CREATE -> after

            // c -> u : 최신 데이터인 after를 선택하고 대신 op는 c로 변경
            // u -> u : latest
            // d -> u : 비정상, '미노출 되어야 하는데 노출'되는 것보다 '노출되어야 하는데 미노출'되는 것이 상대적으로 나아 d 수행
            before.op == Operation.CREATE && after.op == Operation.UPDATE -> after.apply { op = Operation.CREATE }
            before.op == Operation.UPDATE && after.op == Operation.UPDATE -> after
            before.op == Operation.DELETE && after.op == Operation.UPDATE -> before

            // after가 delete면 이전 event는 중요하지 않음 (무조건 delete)
            after.op == Operation.DELETE -> after

            else -> null
        }

    fun diffLog(before: ChangedData<*>, after: ChangedData<*>): String =
        "${before.op} -> ${after.op}, " +
                "before=(partition=${before.partition},offset=${before.offset},id=${before.id}), " +
                "after=(partition=${after.partition},offset=${after.offset},id=${after.id})"
}

