import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.Catalog
import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.enums.Operation
import com.cowave.shared.utils.logger

object CatalogMergeStrategy : MergeStrategy<Catalog> {
    private val logger by logger()

    override fun merge(documents: List<ChangedData<Catalog>>): List<ChangedData<Catalog>> {
        return documents
            .groupBy { it.id } // 같은 문서로 그룹핑
            .map { (_, group) ->
                if (group.size == 1) {
                    group.first()
                } else {
                    var isChangedCategory = false
                    var isChangedBrand = false
                    var isChangedManufacturer = false

                    group.sortedBy { it.offset } // offset 기준으로 정렬
                        .fold(null as ChangedData<Catalog>?) { acc, current ->
                            when (current.op) {
                                Operation.CREATE -> {
                                    isChangedCategory = true
                                    isChangedBrand = true
                                    isChangedManufacturer = true
                                }
                                Operation.UPDATE -> {
                                    // Note. update 메시지의 before가 null인 경우 존재
                                    if (current.beforeData != null && current.afterData != null) {
                                        current.beforeData.`id$1`
                                        current.beforeData.categoryId
                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
                                        if (current.beforeData.manufacturerId != current.afterData.manufacturerId) isChangedManufacturer = true
                                    }
                                }
                                Operation.DELETE -> {
                                    isChangedCategory = false
                                    isChangedBrand = false
                                    isChangedManufacturer = false
                                }
                            }

                            merge(acc, current)
                                .also {
                                    if (it == null) {
                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
                                        logger.warn { "[CatalogMergeStrategy] Unexpected operation. "  + diffLog(acc!!, current) }
                                    }
                            }
                        }
                        .apply {
                            this?.shouldFetchCategory = isChangedCategory
                            this?.shouldFetchBrand = isChangedBrand
                            this?.shouldFetchManufacturer = isChangedManufacturer
                        }
                }
            }
            .filterNotNull()
    }
}

