                    group
                        .sortedBy { it.offset } // offset 기준으로 정렬
                        .fold(null as ChangedData<Product>?) { acc, current ->
                            when (current.op) {
                                Operation.CREATE -> {
                                    isChangedCategory = true
                                    // Note. product의 brand, manufacturer 연동은 아직 되고 있지 않지만 미리 작업해둠
                                    isChangedBrand = true
                                    isChangedManufacturer = true
                                    isChangedMall = true
                                }

                                Operation.UPDATE -> {
                                    // Note. update 메시지의 before가 null인 경우 존재
                                    if (current.beforeData != null && current.afterData != null) {
                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
                                        if (current.beforeData.manufacturerId !=
                                            current.afterData.manufacturerId
                                        ) {
                                            isChangedManufacturer = true
                                        }
                                        if (current.beforeData.mallId != current.afterData.mallId) isChangedMall = true
                                    }
                                }

                                Operation.DELETE -> {
                                    isChangedCategory = false
                                    isChangedBrand = false
                                    isChangedManufacturer = false
                                    isChangedMall = false
                                }
                            }

                            merge(acc, current)
                                .also {
                                    if (it == null) {
                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
                                        logger.warn { "[ProductMergeStrategy] Unexpected operation. " + diffLog(acc!!, current) }
                                    }
                                }
                        }.apply {
                            this?.shouldFetchCategory = isChangedCategory
                            this?.shouldFetchBrand = isChangedBrand
                            this?.shouldFetchManufacturer = isChangedManufacturer
                            this?.shouldFetchMall = isChangedMall
                        }
                }
            }.filterNotNull()
}

