data class CatalogDocument(
    override val id: Long,
    override val name: String, // Note. copy_to `searchField`
    override val categoryId: Int,
    override val categoryId1: Int,
    override val categoryId2: Int? = null,
    override val categoryId3: Int? = null,
    override val categoryId4: Int? = null,
    override val categoryNames: String, // Note. copy_to `searchField`
    override val isActiveCategory: Boolean,
    override val brandId: Long,
    override val brandName: String, // Note. copy_to `searchField`
    override val manufacturerId: Long,
    override val manufacturerName: String, // Note. copy_to `searchField`
    val enuriId: Long?,
    val mainCatalogId: Long,
    val bundleName: String? = null, // Note. copy_to `searchField`
    val bundleDisplaySequence: Int = 0,
    val modelKeywords: String? = null,
    val briefDescription: String? = null, // Note. copy_to `searchField`
    val isAutoCreate: Boolean,
    val isDisplayed: Boolean,
    val isPriceLocked: Boolean,
    val hasAiMatch: Boolean,
    val unit: String? = null,
    val attributeIds: List<Int> = emptyList(),
    val attributeNames: String? = null,
    override val isUsedRental: Boolean = false,
    override val registeredAt: Instant,
    override val createdAt: Instant,
    override val updatedAt: Instant,
    override val danawa: CatalogChannelData,
    override val enuri: CatalogChannelData,
) : IntegratedDocument {
    override val totalSearchable: Boolean = true

    private fun updateDisplay() {
        danawa.status.display = Policy.determineDisplay(this.isActiveCategory, this.isDisplayed, this.danawa.status.catalogStatus)
        enuri.status.display = Policy.determineDisplay(this.isActiveCategory, this.isDisplayed, this.enuri.status.catalogStatus)
    }

    private fun updateIsLargePriceGap() {
        danawa.status.isLargePriceGap = danawa.price?.let {
            Policy.determineIsLargePriceGap(it.lowestPrice, it.averagePrice)
        }
        enuri.status.isLargePriceGap = enuri.price?.let {
            Policy.determineIsLargePriceGap(it.lowestPrice, it.averagePrice)
        }
    }

    private fun updateIsCoupangLowest() {
        danawa.status.isCoupangLowest = danawa.price?.let {
            Policy.determineIsCoupangLowest(it.lowestPrice, it.membershipPrice)
        }
        enuri.status.isCoupangLowest = enuri.price?.let {
            Policy.determineIsCoupangLowest(it.lowestPrice, it.membershipPrice)
        }
    }

    override fun applyDocumentPolicy() {
        updateDisplay()
        updateIsLargePriceGap()
        updateIsCoupangLowest()
    }

    init {
        this.applyDocumentPolicy()
    }

    companion object {
        const val SEARCH_FIELD_NAME = "searchField" // Note. `searchField`는 ES에서 copy_to로 만들어지는 필드
    }

    object Policy {
        fun determineDisplay(
            isActiveCategory: Boolean,
            isDisplayed: Boolean,
            catalogStatus: CatalogStatus?,
        ): Boolean =
            isActiveCategory && isDisplayed && catalogStatus == CatalogStatus.PRICE_COMPARISON

        fun determineIsLargePriceGap(
            lowestPrice: Int,
            averagePrice: Int?,
        ): Boolean =
            if (averagePrice != null && averagePrice > 0) {
                lowestPrice <= averagePrice / 2
            } else false

        fun determineIsCoupangLowest(
            lowestPrice: Int,
            membershipPrice: Int?
        ): Boolean =
            if (membershipPrice != null && membershipPrice > 0) {
                membershipPrice < lowestPrice
            } else false

        fun determineModelKeywords(keywordModels: List<KeywordModel>?): String? =
            keywordModels?.map { it.modelKeyword }?.joinToString(" ") { it }

        fun determineAttributeIds(attributeValues: List<CatalogAttributeValue>?): List<Int> =
            attributeValues?.map { it.attributeValueId } ?: emptyList()

        fun determineAttributeValues(attributeValues: List<CatalogAttributeValue>?): String? =
            attributeValues?.map { it.attributeValueName }?. joinToString(" ") { it }

        // Caution. UsedRentalDetector 사용이 지속가능성/유지보수성이 낮아 구현은 해두었지만 사용은 보류합니다.
        fun determineIsUsedRental(name: String, categoryId1: Int): Boolean =
            UsedRentalDetector.isUsedOrRentalForCatalog(name, categoryId1)
    }
}

