            arrayOf("현금", "사은품"),
            arrayOf("개월", "의무"),
        )

    /**
     * @param category1 카테고리 코드
     * @param name 모델명/상품명
     */
    fun isUsedOrRentalForCatalog(
        name: String,
        categoryId1: Int,
    ): Boolean {
        var usedOrRental = false // 중고/렌탈 여부

        // 1. 검사 대상 문자열 결정
        if (categoryId1 == 1841 || categoryId1 == 22591) {
            // NOTE. 다나와 에누리 공용 물리카테고리 도서(1841), 문구/다이어리(22591)일 경우 false를 반환한다.
            return false
        }

        // 1-1. 단어 경계 체크
        if (name.isNotEmpty()) {
            val normalized = normalize(name)
            val tokens = analyzeTokens(normalized)

            for (token in tokens) {
                if (EXT_CONDI_KEYWORD_G1.contains(token)) {
                    usedOrRental = true
                    break
                }
            }

            // 1-2. 단어 경계 무시 키워드
            if (!usedOrRental) {
                val lowerName = name
                for (keyword in EXT_CONDI_KEYWORD_G2) {
                    if (lowerName.contains(keyword)) {
                        usedOrRental = true
                        break
                    }
                }
            }
        }
        return usedOrRental
    }

    fun isUsedOrRentalForProduct(name: String): Boolean {
        var usedOrRental = false // 중고/렌탈 여부
        // 1-1. 단어 경계 문자 치환 후 키워드 체크
        val buffer = StringBuilder()
        var spaceCount = 0

        // 단어 경계 문자를 공백으로 치환, 연속 공백 제거
        for (char in name) {
            var c = char
            if (EXT_CONDI_BOUNDARY.contains(c)) {
                c = ' '
            }

            if (c == ' ') {
                spaceCount++
            } else {
                spaceCount = 0
            }

            if (spaceCount < 2) {
                buffer.append(c)
            }
        }

        val target = buffer.toString()

        // P1 키워드 체크
        val lowerTarget = target.lowercase()
        for (keyword in EXT_CONDI_KEYWORD_P1) {
            if (lowerTarget.contains(keyword)) {
                usedOrRental = true
                break
            }
        }

        // 1-2. 복합 키워드 체크
        if (!usedOrRental) {
            for (combo in EXT_CONDI_KEYWORD_P2) {
                var matchCount = 0
                for (keyword in combo) {
                    if (target.contains(keyword)) {
                        matchCount++
                    } else {
                        break
                    }
                }
                if (matchCount == combo.size) {
                    usedOrRental = true
                    break
                }
            }
        }
        return usedOrRental
    }

    private fun normalize(text: String): String {
        if (text.isBlank()) return ""

        val sb = StringBuilder(text.length)

        // 1. 전각 → 반각 변환 + 소문자 변환
        for (c in text) {
            var ch = c
            // 전각문자(！～) → 반각문자(!~) 변환
            if (ch in '！'..'～') {
                ch = (ch.code - 0xFEE0).toChar()
            }
            sb.append(ch.lowercaseChar())
        }

        var result = sb.toString()

        // 2. 특수문자 → 공백 (한글, 영문, 숫자, ., & 만 남김), 여러 공백 → 하나로
        result = result.replace(Regex("[^ㄱ-ㅎㅏ-ㅣ가-힣a-z0-9.&\\s]+|\\s+"), " ").trim()

        return result
    }

    private fun analyzeTokens(text: String): Array<String> =
        BOUNDARY_REGEX
            .split(text)
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .toTypedArray()
}

