package com.cowave.search.application.index.service

import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.Catalog
import com.cowave.search.application.index.dto.DependencyId
import com.cowave.search.application.index.mapper.toIndexDocument
import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.dto.IndexDocument
import com.cowave.search.domain.index.enums.Operation
import com.cowave.search.domain.search.document.CatalogDocument
import org.springframework.stereotype.Service

@Service
class CatalogAssembleService(
    private val proxyApplicationService: ProxyApplicationService,
) {
    fun assemble(documents: List<ChangedData<Catalog>>): List<IndexDocument<CatalogDocument>> {
        val dependencyId = getDependencyId(documents)
        val dependency = proxyApplicationService.fetchDependencies(dependencyId)

        return documents.map {
            // Note. CREATE 시 fetchDependencies()로부터 category, brand, manufacturer를 모두 받아와야 CatalogDocument를 생성할 수 있다.
            if (it.op == Operation.CREATE) {
                require(it.afterData != null) {
                    "Failed to assemble catalog. afterData must not be null for create operation"
                }
                require(
                    dependency.categories[it.afterData!!.categoryId] != null &&
                        dependency.brands[it.afterData!!.brandId] != null &&
                        dependency.manufacturers[it.afterData!!.manufacturerId] != null,
                ) {
                    "Failed to assemble catalog. Category, Brand, and Manufacturer must not be null. catalogId=[${it.id}]"
                }
            }

            it.toIndexDocument(
                category = dependency.categories[it.afterData?.categoryId],
                brand = dependency.brands[it.afterData?.brandId],
                manufacturer = dependency.manufacturers[it.afterData?.manufacturerId],
            )
        }
    }

    fun getDependencyId(documents: List<ChangedData<Catalog>>): DependencyId {
        val categoryIds: MutableList<Int> = mutableListOf()
        val brandIds: MutableList<Long> = mutableListOf()
        val manufacturerIds: MutableList<Long> = mutableListOf()

        documents.forEach {
            if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
            if (it.shouldFetchBrand) brandIds.add(it.afterData!!.brandId)
            if (it.shouldFetchManufacturer) manufacturerIds.add(it.afterData!!.manufacturerId)
        }

        return DependencyId(
            categoryIds = categoryIds.distinct(),
            brandIds = brandIds.distinct(),
            manufacturerIds = manufacturerIds.distinct(),
        )
    }
}

