import com.cowave.search.domain.proxy.mall.MallService
import com.cowave.search.domain.proxy.manufacturer.Manufacturer
import com.cowave.search.domain.proxy.manufacturer.ManufacturerService
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.runBlocking
import org.springframework.stereotype.Service

@Service
class ProxyApplicationService(
    private val brandService: BrandService,
    private val manufacturerService: ManufacturerService,
    private val categoryService: CategoryService,
    private val mallService: MallService,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            val categoriesDeferred =
                async {
                    if (dependencyId.categoryIds.isEmpty()) {
                        emptyMap()
                    } else {
                        categoryService.getCategories(dependencyId.categoryIds).associateBy { it.id }
                    }
                }
            val brandsDeferred =
                async {
                    if (dependencyId.brandIds.isEmpty()) {
                        emptyMap()
                    } else {
                        brandService.getBrands(dependencyId.brandIds).associateBy { it.id }
                    }
                }
            val manufacturersDeferred =
                async {
                    if (dependencyId.manufacturerIds.isEmpty()) {
                        emptyMap()
                    } else {
                        manufacturerService.getManufacturers(dependencyId.manufacturerIds).associateBy { it.id }
                    }
                }
            val mallsDeferred =
                async {
                    if (dependencyId.mallIds.isEmpty()) {
                        emptyMap()
                    } else {
                        mallService.getMalls(dependencyId.mallIds).associateBy { it.mallId }
                    }
                }

            Dependency(
                categories = categoriesDeferred.await(),
                brands = brandsDeferred.await(),
                manufacturers = manufacturersDeferred.await(),
                malls = mallsDeferred.await(),
            )
        }
}

